INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (2,2,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL ELSE 0 END'),'e9e552add50640e2c01e3201f3cb1a448b4dea7b6bab14dbf7cb67c67df1625f','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (3,3,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL ELSE REGEXP_REPLACE(${column}, ''[[:alnum:]]'', ${param.mask_character}) END'),'02169b6e57647ddf653bab354032f8fb7302b6de5a1de5478eb5c5f83ff33edf','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (4,4,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL WHEN ${param.visible_suffix_length} = 0 THEN REGEXP_REPLACE(${column}, ''[[:digit:]]'', ''*'') ELSE REGEXP_REPLACE(SUBSTR(${column}, 1, GREATEST(LENGTH(${column}) - ${param.visible_suffix_length}, 0)), ''[[:digit:]]'', ''*'') || SUBSTR(${column}, -LEAST(${param.visible_suffix_length}, LENGTH(${column}))) END'),'ec41cd2068d8ba7b4c0c39d7a37537ec0cefc27eb789e9fc883239acc3a9dafd','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (5,5,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL ELSE ADD_MONTHS(TRUNC(${column}, ''YEAR''), ${param.month_number} - 1) + (${param.day_number} - 1) END'),'b6749638540d4586337c0532a11256738e63099c05b70a258e617566b7aaae25','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (6,6,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL ELSE TRUNC(${column}, ''MONTH'') + (${param.day_number} - 1) END'),'0ecf2399a3e02ff5bbf73f434d77c01ceb5be60a8dd45dad1225109dfcba7284','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (7,7,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL ELSE LOWER(RAWTOHEX(STANDARD_HASH(UTL_I18N.STRING_TO_RAW(TO_CHAR(${column}), ''AL32UTF8''), ''SHA256''))) END'),'4ad6cb1b8216bf4046a19620136bdf600b5b11c0b81bdb76675a39769d54c335','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (8,8,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL ELSE DBMS_RANDOM.STRING(''L'', LENGTH(${column})) END'),'d66877a931314356052763d4b35aa13e8c4ea32e743fedc75acfc4795782418e','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (9,9,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL ELSE DBMS_RANDOM.STRING(''U'', LENGTH(${column})) END'),'3154f54bb4e2cfceacc5d8c55c05755ee1b57488fd6a81d91668c36bb3a09aa7','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (10,10,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL WHEN INSTR(${column}, ''@'') > 1 THEN DBMS_RANDOM.STRING(''L'', ${param.local_part_length}) || SUBSTR(${column}, INSTR(${column}, ''@'')) ELSE DBMS_RANDOM.STRING(''L'', ${param.local_part_length}) || ''@invalid.example'' END'),'261c53c0013184757141ef5a2d5002f0903d1c85455a6486b3188ee0c75dd7f9','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (11,11,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL ELSE ${param.prefix} || LPAD(TRUNC(DBMS_RANDOM.VALUE(0, 100000000)), 8, ''0'') END'),'598d6fd05a0839935e7ca5d0db4b09beac83dbdffdb83756f18f378131f6ac3e','PUBLISHED',SYSTIMESTAMP);
INSERT INTO algorithm_implementation(implementation_id,algorithm_version_id,technology_code,implementation_type,implementation_code,code_checksum,status,published_at) VALUES (12,12,'ORACLE','SQL_EXPRESSION',TO_CLOB('CASE WHEN ${column} IS NULL THEN NULL ELSE ROUND(${column} * (1 + DBMS_RANDOM.VALUE(-${param.max_ratio}, ${param.max_ratio})), ${param.scale}) END'),'96ca06865799936674f62addcb53eff28adb29d1b244de1a8bb6332ca597a78a','PUBLISHED',SYSTIMESTAMP);
